#include <stdio.h>

void show(int x) {
    printf("碗里是 %d\n", x);
}

void show_double(int x) {
    printf("翻倍是 %d\n", x * 2);
}

void each(int a[], int n, void (*visit)(int)) {
    for (int i = 0; i < n; i++) {
        visit(a[i]);
    }
}

int main(void) {
    int bowl[3];

    for (int i = 0; i < 3; i++) {
        if (scanf("%d", &bowl[i]) != 1) {
            return 1;
        }
    }

    each(bowl, 3, show);
    each(bowl, 3, show_double);
    return 0;
}

