#include <stdio.h>
#include <stdlib.h>

int cmp(const void *a, const void *b) {
    return (*(const int *)a) - (*(const int *)b);
}

int main(void) {
    int nums[4];

    for (int i = 0; i < 4; i++) {
        if (scanf("%d", &nums[i]) != 1) {
            return 1;
        }
    }

    qsort(nums, 4, sizeof(int), cmp);

    for (int i = 0; i < 4; i++) {
        printf("%d\n", nums[i]);
    }
    printf("最小的 %d，最大的 %d\n", nums[0], nums[4 - 1]);
    return 0;
}

